b(t) from public.editions t where t.id=987240006)='{"id":987240006,"title":"Apollyon","isbn_10":null,"isbn_13":"9789023666486","work_id":987140006,"cover_id":null,"language":"dut","publisher":"Nijgh & Van Ditmar","publish_date":null,"open_library_edition_id":"OL23959221M"}'::jsonb as exact union all select 'catalog_work_descriptions:25' as ref,(select to_jsonb(t) from public.catalog_work_descriptions t where t.work_id=987140006 and t.language='nl')='{"text":"Notaris Ewijk leidt naast zijn beroep een bestaan als schrijver. Op de overtocht naar Engeland ontmoet hij een vroegere schoolgenoot, baron Starnmeer, wiens zelfverzekerde persoonlijkheid hem sterk bezighoudt. Hun contact brengt Ewijks opvattingen over mensen en zijn eigen schrijverschap aan het wankelen. Ook anderen raken binnen de invloedssfeer van de baron. Bordewijk verbindt hun ontmoetingen met vragen over macht, bewondering en de prijs van een levenshouding die nauwelijks ruimte laat voor de zelfstandigheid van anderen.","work_id":987140006,"evidence":[{"note":"Apollyon1941, exact1978DutchHardcover9789023666486, Ewijk/Starnmeer notLeeuwenkuijl(EikenVanDodona). KBoriginal1941 overrides assumption1937.","type":"reviewed_identity_and_bibliography","sources":["https://data.bibliotheken.nl/id/nbt/p780222903"],"reference":"new-work-dossier-readings-041.json#175","checked_at":"2026-11-03T08:39:50.360Z"},{"type":"original_substantive_source_review","review":"content-amendment-017.json","sources":["https://www.dbnl.org/tekst/_ons003198301_01/_ons003198301_01_0116.php","https://www.dbnl.org/tekst/zuid004krit01_01/kll00059.php","https://openlibrary.org/works/OL14904141W","https://data.bibliotheken.nl/id/nbt/p780222903"]},{"type":"explicit_contributor_roles","credits":[],"limitation":"Existing schema has one primary Work author; no synthetic combined-author identity or author merge."},{"note":"Bound official bulk source reviewed once; no verified image available for import. Preserve resolver, inspect actual front/plac